param([Parameter(Mandatory)][string]$FixtureExecutable,[Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$ScratchRoot)
$ErrorActionPreference='Stop';$service=$null;$provider=$null;$checks=0
$root=Join-Path $ScratchRoot ('world-history-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$env:TEMP=$root;$env:TMP=$root;$env:HIBERNATION_SESSION_KEY='world-history-fixture'
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Host "PASS $Name"}
function Await([scriptblock]$Probe,$Name){$end=[DateTime]::UtcNow.AddSeconds(25);while([DateTime]::UtcNow-lt$end){if(&$Probe){return};Start-Sleep -Milliseconds 50};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$p=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer world-history-fixture'};TimeoutSec=10};if($null-ne$Data){$p.Method='Post';$p.ContentType='application/json';$p.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 65 -Compress))};Invoke-RestMethod @p}
function Call($Id,$Tool,$Arguments){@{version=1;kind='call';text=$null;calls=@(@{id=$Id;tool=$Tool;args=$Arguments})}}
function Silent{@{version=1;kind='silence';text=$null;calls=@()}}
function Message($Items){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Items|ForEach-Object {@{response=$_}})}|ConvertTo-Json -Depth 65|Set-Content -LiteralPath (Join-Path $root provider/plan.json) -Encoding utf8;$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text='合成相处：看看以前做过的小事。'};Await {!(Api '/api/chat').busy} 'dialogue';Check (!(Api '/api/chat').call_failed) 'turn completes';$capture=Get-Content -LiteralPath (Join-Path $root provider/last-request.json) -Raw|ConvertFrom-Json -Depth 75;($capture.messages[-1].content|ConvertFrom-Json -Depth 65).tool_results}
function Start-Backend{$script:service=Start-Process -FilePath $Executable -ArgumentList ('--config "'+$configPath+'" --ready-file "'+$ready+'"') -WindowStyle Hidden -PassThru;Await {if($service.HasExited){throw 'history host exited'};if(Test-Path -LiteralPath $ready){return (Get-Content -LiteralPath $ready -Raw|ConvertFrom-Json).pid-eq$service.Id};$false} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content -LiteralPath $ready -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'clean process exit'}
try{
 [IO.File]::WriteAllText((Join-Path $root .synthetic-ai-evaluation),'hibernation.dialogue-evaluation.v1',[Text.UTF8Encoding]::new($false));$seed=& $FixtureExecutable $root legacy-world;Check ($LASTEXITCODE-eq0) 'fresh marked archive seeds actual and pending legacy classifications'
 $providerRoot=Join-Path $root provider;New-Item -ItemType Directory -Force $providerRoot|Out-Null
 $provider=Start-Process -FilePath $ProviderExecutable -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru;Await {Test-Path -LiteralPath (Join-Path $providerRoot port)} 'provider';$fixture='http://127.0.0.1:'+(Get-Content -LiteralPath (Join-Path $providerRoot port))
 $cfg=Get-Content -LiteralPath (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable
 $cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path (Split-Path $Executable) plugins
 $cfg.plugins=@{atelier=@{enabled=$true};pocket=@{enabled=$true;scrambleSteps=3;maximumMoves=24}};$cfg.computer=@{enabled=$false};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.reflectOnActivities=$false;$cfg.maxStartsPerHour=1000
 $cfg.profiles=@($cfg.profiles[0],@{id='actor';label='history fixture';enabled=$true;protocol='chat-completions';origin=$fixture;model='fixture-model';supportsJsonObject=$true});$cfg.review=@{enabled=$false}
 $configPath=Join-Path $root config.json;$ready=Join-Path $root ready.json;$cfg|ConvertTo-Json -Depth 65|Set-Content -LiteralPath $configPath -Encoding utf8;Start-Backend;$null=Api '/api/model' @{id='actor'}
 $r=Message @((Call legacy memory.archive_read @{id='legacy-applied'}),(Silent));$old=$r[0].result.records[0]
 Check ($r[0].ok-and$old.legacy_applied_puzzle-and$old.recorded_kind-eq'tool_intent'-and$old.result.applied-and!$old.result.completed-and$old.result.game.moves-eq1) 'legacy applied action is readable without turning an unfinished game into a win'
 $r=Message @((Call legacyfind memory.archive_search @{query='legacy-board';limit=8}),(Silent));Check (@($r[0].result.records|Where-Object id -eq legacy-applied).Count-eq1-and@($r[0].result.records|Where-Object {$_.id-in@('legacy-pending','legacy-unrelated')}).Count-eq0) 'legacy applied history is searchable without exposing pending or unrelated intents'
 $raw=Api '/api/archive' @{id='legacy-applied'};Check ($raw.records[0].data.kind-eq'tool_intent'-and$raw.records[0].data.result.applied-and$raw.records[0].revision-eq1) 'legacy projection does not rewrite original encrypted history'
 foreach($blocked in @('legacy-pending','legacy-unrelated')){$r=Message @((Call blocked memory.archive_read @{id=$blocked}),(Silent));Check ($r[0].ok-and$r[0].result.records.Count-eq0) 'pending and unrelated intents remain outside readable world history'}
 $r=Message @((Call legacysource memory.archive_read @{id='legacy-applied'}),(Call notice self.notice @{id='legacy-attention';expected_revision=0;kind='interest';topic='以前试过的一格';note='记得当时确实按过，并没有解完';stance='curious';source_ids=@('legacy-applied')}),(Silent));Check ($r[0].ok-and$r[0].result.thread.experience_contexts[0].id-eq'legacy-board') 'retrieved legacy source keeps its raw kind and remains valid evidence for personal interpretation'
 $r=Message @((Call legacyfeeling memory.archive_read @{id='legacy-applied'}),(Call feeling state.appraise @{source_id='legacy-applied';valence=0.2}),(Silent));Check ($r[0].ok-and$r[0].result.accepted) 'an actual legacy move supports a bounded present feeling without changing its original classification'
 $r=Message @((Call pendingfeeling memory.archive_read @{id='legacy-pending'}),(Call feeling state.appraise @{source_id='legacy-pending';valence=0.2}),(Silent));Check (!$r[0].ok-and$r[0].error.code-eq'appraisal_source_not_available') 'an unexecuted legacy proposal cannot become an emotional experience'
 $piece=@{id='old-corner';expected_revision=0;title='留下的角落';kind='story';stage='draft';content='WORLD_HISTORY_PRIVATE 原来这里有半个圆。'}
 $r=Message @((Call write atelier.write $piece),(Silent));$written=$r[0].source_id;Check ($r[0].ok-and$written) 'a real authored piece has its original write receipt'
 $r=Message @((Call keep self.notice @{id='a-small-start';expected_revision=0;kind='intention';topic='留一个故事开头';note='想先留下一小段';stance='want';source_ids=@($written)}),(Silent));Check ($r[0].result.thread.experience_contexts[0].id-eq$piece.id) 'personal concern identifies its actual authored experience'
 $r=Message @((Call append atelier.append @{id=$piece.id;expected_revision=1;stage='draft';content='后来风停了。'}),(Silent));$appended=$r[0].source_id
 $r=Message @((Call read atelier.read @{id=$piece.id}),(Silent));$read=$r[0].source_id;$pastContent=$r[0].result.piece.content
 $r=Message @((Call start pocket.start @{}),(Silent));$game=$r[0].result.game;$oldGame=$game.id;$started=$r[0].source_id
 $r=Message @((Call keep self.notice @{id='an-old-board';expected_revision=0;kind='intention';topic='再看看这局';note='想看看剩下的灯';stance='want';source_ids=@($started)}),(Silent));Check ($r[0].result.thread.experience_contexts[0].id-eq$oldGame) 'old puzzle intention retains the identity of its original board'
 $r=Message @((Call leave pocket.leave @{game_id=$game.id;expected_revision=$game.revision}),(Silent));$left=$r[0].source_id;$pastBoard=$r[0].result.game
 $r=Message @((Call new pocket.start @{}),(Silent));$newGame=$r[0].result.game.id;Check ($newGame-ne$oldGame) 'a genuinely new board exists after leaving the old one'
 $newPiece=$piece.Clone();$newPiece.expected_revision=2;$newPiece.content='现在是另一段文字。';$null=Message @((Call rewrite atelier.write $newPiece),(Silent))
 for($i=0;$i-lt5;$i++){$null=Message @((Call later atelier.read @{id=$piece.id}),(Silent))}
 $r=Message @((Call internal state.observe @{}),(Silent));Check ($r[0].ok-and!$r[0].source_id) 'internal state is a current view rather than an invented lived experience'
 $r=Message @((Call history memory.archive_read @{id=$left}),(Silent));$receipt=$r[0].result.records[0]
 Check ($r[0].ok-and$receipt.id-eq$left-and$receipt.revision-eq1-and$receipt.kind-eq'tool_observation'-and$receipt.historical_only-and$receipt.result.applied-and!$receipt.result.completed) 'past play is readable by its original identity without pretending it solved the game'
 Check ($receipt.result.game.id-eq$oldGame-and$receipt.result.game.status-eq'left'-and$receipt.result.game.lit_count-eq$pastBoard.lit_count) 'historical result remains the actual left board after a new game starts'
 $r=Message @((Call find memory.archive_search @{query=$oldGame;limit=8}),(Silent));Check (@($r[0].result.records|Where-Object {$_.tool-eq'pocket.leave'-and$_.id-eq$left}).Count-eq1) 'old world receipts can be found by their real object id beyond recent context'
 $r=Message @((Call self self.observe @{query=$oldGame}),(Silent));Check ($r[0].result.threads[0].id-eq'an-old-board'-and$r[0].result.threads[0].status-eq'active'-and$r[0].result.threads[0].experience_contexts[0].id-ne$newGame) 'origin lookup neither reassigns an old intention to the new game nor auto-closes it'
 $r=Message @((Call log memory.archive_search @{query='state.observe';limit=8}),(Silent));Check ($r[0].ok-and$r[0].result.records.Count-eq0) 'internal state tool invocations create no readable original experience'
 $r=Message @((Call oldwrite memory.archive_read @{id=$written}),(Silent));Check ($r[0].result.records[0].observed_text_scope-eq'applied_whole_piece'-and$r[0].result.records[0].text.Contains($piece.content)-and!$r[0].result.records[0].text.Contains($newPiece.content)) 'actual old written content is retained without reading back the new file as history'
 $r=Message @((Call oldappend memory.archive_read @{id=$appended}),(Silent));Check ($r[0].result.records[0].observed_text_scope-eq'applied_append_fragment'-and$r[0].result.records[0].text.Contains('后来风停了。')-and!$r[0].result.records[0].text.Contains($piece.content)) 'append receipt exposes only the actually applied fragment'
 $r=Message @((Call oldread memory.archive_read @{id=$read}),(Silent));Check ($r[0].result.records[0].text.Contains($pastContent)-and$r[0].result.records[0].result.piece.revision-eq2) 'past observed work retains exactly the content and version originally read'
 $digest=@{summary='当时实际放下了一局未解的九盏灯，没有赢。';keywords=@($oldGame,'主动放下');uncertainties=@('这是过去的状态，不说明新局如何。')}
 $r=Message @((Call original memory.archive_read @{id=$left}),(Call compact memory.compact @{id=$left}),$digest,(Silent));$digestId=$r[0].result.id;Check ($r[0].ok-and$digestId) 'known historical experience can be condensed through the existing manager path'
 $r=Message @((Call condensed memory.read @{id=$digestId}),(Silent));Check ($r[0].result.memories[0].kind-eq'summary'-and$r[0].result.memories[0].sources[0].id-eq$left-and$r[0].result.memories[0].sources[0].kind-eq'tool_observation') 'condensation retains the actual original source rather than inventing independent experience'
 $r=Message @((Call source memory.archive_read @{id=$written}),(Call done self.close @{id='a-small-start';expected_revision=1;outcome='completed';note='当时那个开头确实已留下';source_ids=@($written)}),(Silent));Check ($r[0].ok-and$r[0].result.thread.status-eq'completed') 'a retrieved actual result can support the matching small intention after recent context has moved on'
 $r=Message @((Call source memory.archive_read @{id=$written}),(Call restrict memory.remember @{kind='outer';text='用于检查原始作品经历的可访问性';source_ids=@($written)}),(Silent));$memory=$r[0].result.id;Check ([bool]$memory) 'an actual retrieved original can have an owner-controlled access boundary';$null=Api '/api/access' @{id=$memory;accessible=$false}
 $r=Message @((Call hidden memory.archive_read @{id=$written}),(Silent));Check (!$r[0].ok-and$r[0].error.code-eq'memory_not_accessible') 'source restrictions apply equally to historical world projections'
 $r=Message @((Call hidden_self self.observe @{query='留一个故事开头';status='all'}),(Silent));Check ($r[0].result.threads.Count-eq0) 'restricted origins cannot leak through personal experience identities'
 Check ((Api '/api/archive' @{id=$written}).records[0].data.written_content-eq$piece.content) 'owner raw encrypted archive still retains the unchanged original'
 $null=Api '/api/access' @{id=$memory;accessible=$true};Stop-Backend;Start-Backend
 $r=Message @((Call persisted memory.archive_read @{id=$left}),(Silent));Check ($r[0].result.records[0].result.game.id-eq$oldGame-and$r[0].result.records[0].result.game.status-eq'left') 'historical truth persists through an actual backend restart'
 Stop-Backend;Check (!([Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes((Join-Path $cfg.dataRoot archive/records.sqlite))).Contains('WORLD_HISTORY_PRIVATE'))) 'historical applied text remains encrypted on disk'
 @{completed=$true;checks=$checks;root=$root}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $root acceptance.json);Write-Output "World history passed: $checks checks. Evidence: $root"
}finally{foreach($process in @($service,$provider)){if($process){$process.Refresh();if(!$process.HasExited){Stop-Process -Id $process.Id}}}}
